CREATE TABLE client (
  num_cli INT PRIMARY KEY,
  nom VARCHAR(40) NOT NULL
);

CREATE TABLE habit (
  num_hab INT PRIMARY KEY,
  libelle VARCHAR(50) NOT NULL,
  prix DECIMAL(6, 2) CHECK (prix > 0)
);

CREATE TABLE location (
  num_cli INT NOT NULL,
  num_hab INT NOT NULL,
  date_loc DATE NOT NULL,
  duree INT DEFAULT 1 CHECK (duree >= 1),
  PRIMARY KEY (num_cli, num_hab, date_loc),
  FOREIGN KEY (num_cli) REFERENCES client(num_cli),
  FOREIGN KEY (num_hab) REFERENCES habit(num_hab)
);

ALTER TABLE habit ADD COLUMN stock INT DEFAULT 0;
ALTER TABLE habit ADD CONSTRAINT chk_stock CHECK (stock >= 0);
ALTER TABLE habit MODIFY libelle VARCHAR(80) NOT NULL;
ALTER TABLE habit DROP COLUMN stock;

SELECT cin, nom
FROM candidat
WHERE code_sec IN (SELECT code_sec FROM section WHERE libelle LIKE '%Info%');

SELECT nom FROM candidat WHERE nom LIKE 'B%';

SELECT s.libelle, COUNT(c.cin) AS effectif
FROM section s
LEFT JOIN candidat c ON c.code_sec = s.code_sec
GROUP BY s.code_sec, s.libelle;

SELECT ROUND(100 * SUM(moyenne >= 10) / COUNT(*), 1) AS pourcentage_admis
FROM candidat;

SELECT cin, nom FROM candidat
WHERE date_naiss BETWEEN '2006-01-01' AND '2006-12-31';
